import assert from 'node:assert/strict';
import * as THREE from 'three';
import { SingaporeFerrisWheel } from '../src/game/circuits/singapore/SingaporeFerrisWheel.ts';
import { C3_FERRIS_WHEEL_PLACEMENT } from '../src/game/circuits/singapore/SingaporeFerrisWheelLayout.ts';

function exactVertexBounds(root: THREE.Object3D): THREE.Box3 {
  const result = new THREE.Box3(), vertex = new THREE.Vector3(), instance = new THREE.Matrix4(), world = new THREE.Matrix4();
  root.traverse(object => {
    if (!(object instanceof THREE.Mesh)) return;
    const position = object.geometry.getAttribute('position');
    const count = object instanceof THREE.InstancedMesh ? object.count : object instanceof THREE.BatchedMesh ? object.instanceCount : 1;
    for (let i = 0; i < count; i++) {
      if (object instanceof THREE.InstancedMesh || object instanceof THREE.BatchedMesh) {
        object.getMatrixAt(i, instance); world.multiplyMatrices(object.matrixWorld, instance);
      } else world.copy(object.matrixWorld);
      for (let j = 0; j < position.count; j++) result.expandByPoint(vertex.fromBufferAttribute(position, j).applyMatrix4(world));
    }
  });
  return result;
}

assert.throws(() => new SingaporeFerrisWheel(NaN), RangeError);
assert.throws(() => new SingaporeFerrisWheel(Infinity), RangeError);
const wheel = new SingaporeFerrisWheel(-1.25);
assert.equal(wheel.root.name, 'C3_FerrisWheel');
assert.deepEqual(wheel.root.position.toArray(), [-100, 0, -40]);
assert.equal(wheel.diagnostics.cabins, 32);
assert.equal(wheel.diagnostics.radius, 28.7);
assert.equal(wheel.diagnostics.angularSpeed, 0.035);
const pivot = wheel.root.getObjectByName('C3_FerrisWheelSpinPivot')!;
const rotor = wheel.root.getObjectByName('C3_FerrisWheelRotor')!;
assert.ok(pivot && rotor);
const meshes: THREE.Mesh[] = [], cabinMeshes: (THREE.InstancedMesh | THREE.BatchedMesh)[] = [];
wheel.root.traverse(o => {
  assert.equal(o instanceof THREE.Light, false, 'the component must not add lights');
  if (o instanceof THREE.Mesh) {
    meshes.push(o);
    assert.equal(o.layers.isEnabled(0), true); assert.equal(o.layers.isEnabled(1), true);
    assert.equal(o.userData.c3NoShadow, !o.castShadow);
    assert.equal(o.matrixWorldAutoUpdate, true, 'moving-parent world transforms remain live');
    if (o.name.startsWith('C3_FerrisWheelCabins_')) cabinMeshes.push(o as THREE.InstancedMesh | THREE.BatchedMesh);
  }
});
assert.ok(cabinMeshes.length > 1);
assert.equal(cabinMeshes.filter(o => o instanceof THREE.BatchedMesh).length, 1);
const glassBatch = cabinMeshes.find(o => o instanceof THREE.BatchedMesh) as THREE.BatchedMesh;
assert.equal(glassBatch.instanceCount, 32);
assert.equal(glassBatch.sortObjects, true); assert.equal(glassBatch.perObjectFrustumCulled, true);
const glass = glassBatch.material as THREE.MeshPhysicalMaterial;
assert.equal(glass.opacity, 0.46); assert.equal(glass.metalness, 0.52); assert.equal(glass.clearcoat, 1);
const glassPositions = glassBatch.geometry.getAttribute('position');
let glassMinY = Infinity, glassMaxY = -Infinity;
for (let i = 0; i < glassPositions.count; i++) { glassMinY = Math.min(glassMinY, glassPositions.getY(i)); glassMaxY = Math.max(glassMaxY, glassPositions.getY(i)); }
assert.ok(glassMinY < -3 && glassMaxY < -1.5, 'the cabin child offset -3.28 must be baked through its complete hierarchy');
const rotorLocal = new THREE.Box3();
rotor.traverse(o => { if (o instanceof THREE.Mesh && !(o instanceof THREE.InstancedMesh)) { o.geometry.computeBoundingBox(); rotorLocal.union(o.geometry.boundingBox!); } });
assert.ok(rotorLocal.min.x < -29 && rotorLocal.max.x > 29);
assert.ok(rotorLocal.max.y > 64 && rotorLocal.min.z > -5.1 && rotorLocal.max.z < 5.1, 'original torus rings remain vertical in XY, not horizontal in XZ');
const rotorMesh = rotor.children.find(o => o instanceof THREE.Mesh) as THREE.Mesh;
wheel.root.updateMatrixWorld(true); const initialMatrix = rotorMesh.matrixWorld.clone();
wheel.setTime(10); wheel.root.updateMatrixWorld(true);
assert.ok(Math.abs(pivot.rotation.z - 0.35) < 1e-12); assert.equal(pivot.rotation.y, 0);
assert.notDeepEqual(rotorMesh.matrixWorld.elements, initialMatrix.elements, 'the rotor follows its moving axle');
const matrix = new THREE.Matrix4();
for (const batch of cabinMeshes) {
  const count = batch instanceof THREE.BatchedMesh ? batch.instanceCount : batch.count;
  assert.equal(count, 32);
  for (let i = 0; i < count; i++) {
    batch.getMatrixAt(i, matrix);
    const e = matrix.elements, angle = i / 32 * Math.PI * 2 + 0.35;
    assert.ok(Math.abs(e[12] - Math.cos(angle) * 29.18) < 1e-4);
    assert.ok(Math.abs(e[13] - (35.2 + Math.sin(angle) * 29.18)) < 1e-4);
    assert.ok(Math.abs(e[14] - 2.8) < 1e-5);
    for (const k of [0, 5, 10]) assert.equal(e[k], 1);
    for (const k of [1, 2, 4, 6, 8, 9]) assert.equal(e[k], 0, 'cabins stay upright, without spinning with the rim');
  }
}
for (const t of [0, 4, 23, 61, 97]) {
  wheel.setTime(t); wheel.root.updateMatrixWorld(true);
  const box = exactVertexBounds(wheel.root);
  assert.ok(box.min.x >= C3_FERRIS_WHEEL_PLACEMENT.x - 33 && box.max.x <= C3_FERRIS_WHEEL_PLACEMENT.x + 33);
  assert.ok(box.min.z >= C3_FERRIS_WHEEL_PLACEMENT.z - 33 && box.max.z <= C3_FERRIS_WHEEL_PLACEMENT.z + 33);
}
wheel.setTime(0); wheel.update(2);
assert.ok(Math.abs(pivot.rotation.z - 0.00175) < 1e-12, 'stall delta is limited to source 0.05 s');
const beforeInvalid = pivot.rotation.z;
for (const dt of [0, -1, NaN, Infinity]) wheel.update(dt);
wheel.setTime(-1); wheel.setTime(NaN);
assert.equal(pivot.rotation.z, beforeInvalid);
const ownedGeometry = new Set(meshes.map(m => m.geometry));
const ownedMaterials = new Set(meshes.flatMap(m => Array.isArray(m.material) ? m.material : [m.material]));
const disposalCounts = new Map<object, number>();
for (const resource of [...ownedGeometry, ...ownedMaterials]) { disposalCounts.set(resource, 0); resource.addEventListener('dispose', () => disposalCounts.set(resource, disposalCounts.get(resource)! + 1)); }
const parent = new THREE.Group(); parent.add(wheel.root);
wheel.dispose(); wheel.dispose(); wheel.update(1);
assert.equal(parent.children.length, 0); assert.equal(wheel.root.children.length, 0);
for (const count of disposalCounts.values()) assert.equal(count, 1, 'each geometry/material is disposed exactly once, including BatchedMesh-owned packed geometry');
console.log('PASS: complete source hierarchy, original PBR glass, vertical XY rings, Z-axis rotation, upright cabins, layers, safe bounds, delta handling and idempotent deduplicated resource disposal.');
console.log(JSON.stringify(wheel.diagnostics, null, 2));

import * as THREE from 'three';
import { createFerrisWheelPrototype } from './FerrisWheelPrototype.js';
import { C3_FERRIS_WHEEL_PLACEMENT, validateC3FerrisWheelPlacement } from './SingaporeFerrisWheelLayout';

/** The supplied complete model, attached to the existing Circuit 3 render loop. */
export class SingaporeFerrisWheel {
  readonly root: THREE.Group;
  readonly diagnostics: Record<string, unknown>;
  private readonly model: ReturnType<typeof createFerrisWheelPrototype>;
  private elapsed = 0;
  private disposed = false;

  constructor(seaLevel: number) {
    if (!Number.isFinite(seaLevel)) throw new RangeError('Ferris-wheel sea level must be finite');
    const layout = validateC3FerrisWheelPlacement();
    if (!layout.valid) throw new RangeError(`Unsafe ferris-wheel layout: ${layout.problems.join('; ')}`);
    this.model = createFerrisWheelPrototype();
    this.root = this.model.root;
    const placement = C3_FERRIS_WHEEL_PLACEMENT;
    this.root.position.set(placement.x, seaLevel + placement.baseHeightAboveSea, placement.z);
    this.root.rotation.y = placement.yaw;
    this.root.updateMatrix(); this.root.matrixAutoUpdate = false;
    this.model.setAngle(0); this.root.updateMatrixWorld(true);

    // The host shadow bubble reads geometry bounds, rather than InstancedMesh bounds.
    // Give cabin batches their complete sweep envelope while BatchedMesh retains its
    // own precise per-instance geometry bounds for each main/mirror/shadow camera.
    for (const batch of this.model.cabinBatches) {
      batch.mesh.geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(0, 32.8, 2.8), 34.7);
    }
    const geometries = new Set<THREE.BufferGeometry>(), materials = new Set<THREE.Material>();
    let meshes = 0, logicalTriangles = 0, drawBatches = 0, instancedBatches = 0, glassBatches = 0;
    this.root.traverse(object => {
      if (!(object instanceof THREE.Mesh)) return;
      meshes++; drawBatches++; geometries.add(object.geometry);
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) materials.add(material);
      const triangles = (object.geometry.index?.count ?? object.geometry.getAttribute('position').count) / 3;
      if (object instanceof THREE.BatchedMesh) { glassBatches++; logicalTriangles += triangles * object.instanceCount; }
      else if (object instanceof THREE.InstancedMesh) { instancedBatches++; logicalTriangles += triangles * object.count; }
      else logicalTriangles += triangles;
    });
    this.diagnostics = {
      source: 'User-provided noria_optimizada.html; original geometric construction and PBR materials',
      ...this.model.parameters,
      placement: { ...placement, baseWorldY: this.root.position.y, seaLevel }, layout,
      fullDetail: true, lodOrDecimation: false, preservedCabinHierarchy: true,
      transparentTechnique: 'Shared glass geometry; BatchedMesh per-camera instance sorting and culling',
      staticTechnique: 'Source material-compatible mesh merging; immutable local matrices with live parent transforms',
      meshes, drawBatches, instancedBatches, glassBatches, uniqueGeometries: geometries.size,
      uniqueMaterials: materials.size, logicalTriangles,
      extraLights: 0, extraRenderLoops: 0, extraReflectionCameras: 0,
      rigidMarineFoundation: true, physicsBodies: 0, angle: 0,
    };
    this.root.userData.c3FerrisWheel = this.diagnostics;
  }

  /** One visual update per rendered frame; no physics substeps or new RAF loop. */
  update(dt: number): void {
    if (this.disposed || !Number.isFinite(dt) || dt <= 0) return;
    this.setTime(this.elapsed + Math.min(dt, 0.05));
  }

  /** Deterministic phase for reproducible screenshot and animation tests. */
  setTime(time: number): void {
    if (this.disposed || !Number.isFinite(time) || time < 0) return;
    this.elapsed = time;
    const angle = (time * this.model.parameters.angularSpeed) % (Math.PI * 2);
    this.model.setAngle(angle);
    this.diagnostics.angle = angle;
  }

  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.root.removeFromParent();
    const geometries = new Set<THREE.BufferGeometry>(), materials = new Set<THREE.Material>(), textures = new Set<THREE.Texture>();
    this.root.traverse(object => {
      if (!(object instanceof THREE.Mesh)) return;
      if (object instanceof THREE.BatchedMesh) object.dispose(); // Owns its packed geometry and internal data textures.
      else {
        geometries.add(object.geometry);
        if (object instanceof THREE.InstancedMesh) object.dispose(); // Instance buffers only; geometry is shared/deduplicated below.
      }
      for (const material of Array.isArray(object.material) ? object.material : [object.material]) {
        materials.add(material);
        for (const value of Object.values(material)) if (value instanceof THREE.Texture) textures.add(value);
      }
    });
    for (const texture of textures) texture.dispose();
    for (const material of materials) material.dispose();
    for (const geometry of geometries) geometry.dispose();
    this.root.clear();
  }
}

import { SINGAPORE_WAYPOINTS } from './SingaporeWaypoints';
import { MARITIME_PLACEMENTS, isInsideTrackPolygon, type MaritimePlacement } from './SingaporeMaritimeLayout';

export interface FerrisWheelPlacement {
  x: number;
  z: number;
  yaw: number;
  baseHeightAboveSea: number;
  /** Conservative horizontal envelope, including every moving cabin. */
  safetyRadius: number;
}

/** Rigid marine landmark, inside the route; it does not follow waves or add physics bodies. */
export const C3_FERRIS_WHEEL_PLACEMENT: Readonly<FerrisWheelPlacement> = Object.freeze({
  x: -100,
  z: -40,
  yaw: 0,
  baseHeightAboveSea: 1.25,
  safetyRadius: 33,
});

function distanceToTrack(x: number, z: number): number {
  let minimum = Infinity;
  for (let i = 0; i < SINGAPORE_WAYPOINTS.length; i++) {
    const a = SINGAPORE_WAYPOINTS[i];
    const b = SINGAPORE_WAYPOINTS[(i + 1) % SINGAPORE_WAYPOINTS.length];
    const dx = b.x - a.x, dz = b.z - a.z;
    const t = Math.max(0, Math.min(1, ((x - a.x) * dx + (z - a.z) * dz) / (dx * dx + dz * dz || 1)));
    minimum = Math.min(minimum, Math.hypot(x - a.x - dx * t, z - a.z - dz * t));
  }
  return minimum;
}

export function validateC3FerrisWheelPlacement(
  placement: Readonly<FerrisWheelPlacement> = C3_FERRIS_WHEEL_PLACEMENT,
  vessels: readonly MaritimePlacement[] = MARITIME_PLACEMENTS,
) {
  const problems: string[] = [];
  const finite = Object.values(placement).every(Number.isFinite);
  if (!finite || placement.safetyRadius <= 0 || placement.baseHeightAboveSea < 0.6) {
    return { valid: false, problems: ['Invalid ferris-wheel placement or marine deck height'], insideTrack: false, centrelineDistance: 0, clearWaterBeyondRoadbed: 0, minimumVesselGap: 0, nearestVessel: null as string | null };
  }
  // A circular envelope is deliberately stricter than the wheel's real X/Z footprint.
  const insideTrack = isInsideTrackPolygon(placement) && Array.from({ length: 64 }, (_, i) => {
    const angle = i * Math.PI * 2 / 64;
    return isInsideTrackPolygon({ x: placement.x + Math.cos(angle) * placement.safetyRadius, z: placement.z + Math.sin(angle) * placement.safetyRadius });
  }).every(Boolean);
  if (!insideTrack) problems.push('The complete ferris-wheel envelope must remain inside the track polygon');
  const centrelineDistance = distanceToTrack(placement.x, placement.z);
  // Roadbed is bounded by 12.5 m from the centreline in the existing circuit.
  const clearWaterBeyondRoadbed = centrelineDistance - placement.safetyRadius - 12.5;
  if (clearWaterBeyondRoadbed < 10) problems.push('Insufficient clear water between the ferris wheel and the roadbed');
  let minimumVesselGap = Infinity, nearestVessel: string | null = null;
  for (const vessel of vessels) {
    const gap = Math.hypot(vessel.x - placement.x, vessel.z - placement.z) - placement.safetyRadius - Math.hypot(vessel.halfBeam, vessel.halfLength);
    if (gap < minimumVesselGap) { minimumVesselGap = gap; nearestVessel = vessel.id; }
  }
  if (minimumVesselGap < 8) problems.push('Insufficient separation from the existing maritime fleet');
  return { valid: problems.length === 0, problems, insideTrack, centrelineDistance, clearWaterBeyondRoadbed, minimumVesselGap, nearestVessel };
}

import { SINGAPORE_WAYPOINTS } from './SingaporeWaypoints';

export type VesselKind = 'yacht' | 'rescue';
export interface MaritimePlacement {
  id: string;
  kind: VesselKind;
  x: number;
  z: number;
  yaw: number;
  routeFraction: number;
  outwardOffset: number;
  halfBeam: number;
  halfLength: number;
}
export interface XZ { x: number; z: number; }

const route = SINGAPORE_WAYPOINTS;
const lengths = route.map((p, i) => Math.hypot(route[(i + 1) % route.length].x - p.x, route[(i + 1) % route.length].z - p.z));
const totalLength = lengths.reduce((a, b) => a + b, 0);
const signedArea = route.reduce((s, p, i) => s + p.x * route[(i + 1) % route.length].z - route[(i + 1) % route.length].x * p.z, 0);

/** Local -Z is the bow of BOTH supplied models; yaw therefore includes PI. */
export function placementAt(id: string, kind: VesselKind, fraction: number, offset: number, angle = 0): MaritimePlacement {
  let remaining = ((fraction % 1) + 1) % 1 * totalLength;
  let i = 0;
  while (i < lengths.length - 1 && remaining > lengths[i]) remaining -= lengths[i++];
  const a = route[i], b = route[(i + 1) % route.length];
  const t = remaining / lengths[i];
  const previous = route[(i + route.length - 1) % route.length], next = route[(i + 2) % route.length];
  let dx = next.x - previous.x, dz = next.z - previous.z;
  const length = Math.hypot(dx, dz); dx /= length; dz /= length;
  const sign = signedArea > 0 ? 1 : -1;
  return {
    id, kind,
    x: a.x + (b.x - a.x) * t + sign * dz * offset,
    z: a.z + (b.z - a.z) * t - sign * dx * offset,
    yaw: Math.atan2(dx, dz) + Math.PI + angle,
    routeFraction: fraction, outwardOffset: offset,
    // Conservative full-model dimensions, including brightwork / outboard.
    halfBeam: kind === 'yacht' ? 5.4 : 1.85,
    halfLength: kind === 'yacht' ? 22.8 : 4.7,
  };
}

export const MARITIME_PLACEMENTS: readonly MaritimePlacement[] = [
  placementAt('Y01', 'yacht', 0.037, 36, 0.025),
  placementAt('Y02', 'yacht', 0.508, 52, -0.20),
  placementAt('Y03', 'yacht', 0.835, 112, 0.35),
  placementAt('Y04', 'yacht', 0.320, 150, -0.28),
  ...([
    [0.002, 84, 0.15], [0.065, 28, -0.30], [0.130, 90, 0.38],
    [0.205, 30, 0.12], [0.265, 65, -0.28], [0.330, 38, 0.40],
    [0.395, 35, -0.24], [0.460, 28, 0.20], [0.525, 70, -0.16],
    [0.590, 34, 0.32], [0.655, 100, -0.35], [0.720, 40, 0.22],
    [0.785, 28, -0.20], [0.850, 64, 0.35], [0.925, 110, -0.30],
  ] as const).map(([fraction, offset, angle], i) => placementAt(`R${String(i + 1).padStart(2, '0')}`, 'rescue', fraction, offset, angle)),
];

export function isInsideTrackPolygon(p: XZ): boolean {
  let inside = false;
  for (let i = 0, j = route.length - 1; i < route.length; j = i++) {
    const a = route[i], b = route[j];
    if ((a.z > p.z) !== (b.z > p.z) && p.x < (b.x - a.x) * (p.z - a.z) / (b.z - a.z) + a.x) inside = !inside;
  }
  return inside;
}
export function footprint(p: MaritimePlacement): XZ[] {
  const c = Math.cos(p.yaw), s = Math.sin(p.yaw);
  return [[-p.halfBeam, -p.halfLength], [p.halfBeam, -p.halfLength], [p.halfBeam, p.halfLength], [-p.halfBeam, p.halfLength]].map(([x, z]) => ({ x: p.x + c * x + s * z, z: p.z - s * x + c * z }));
}
function pointSegmentDistance(p: XZ, a: XZ, b: XZ): number {
  const dx = b.x - a.x, dz = b.z - a.z;
  const t = Math.max(0, Math.min(1, ((p.x - a.x) * dx + (p.z - a.z) * dz) / (dx * dx + dz * dz || 1)));
  return Math.hypot(p.x - a.x - dx * t, p.z - a.z - dz * t);
}
function cross(a: XZ, b: XZ, c: XZ): number { return (b.x - a.x) * (c.z - a.z) - (b.z - a.z) * (c.x - a.x); }
function segmentDistance(a: XZ, b: XZ, c: XZ, d: XZ): number {
  if (cross(a, b, c) * cross(a, b, d) <= 0 && cross(c, d, a) * cross(c, d, b) <= 0 && Math.max(Math.min(a.x, b.x), Math.min(c.x, d.x)) <= Math.min(Math.max(a.x, b.x), Math.max(c.x, d.x)) && Math.max(Math.min(a.z, b.z), Math.min(c.z, d.z)) <= Math.min(Math.max(a.z, b.z), Math.max(c.z, d.z))) return 0;
  return Math.min(pointSegmentDistance(a, c, d), pointSegmentDistance(b, c, d), pointSegmentDistance(c, a, b), pointSegmentDistance(d, a, b));
}
export function minimumTrackClearance(p: MaritimePlacement): number {
  const corners = footprint(p);
  let min = Infinity;
  for (let i = 0; i < route.length; i++) for (let j = 0; j < 4; j++) min = Math.min(min, segmentDistance(route[i], route[(i + 1) % route.length], corners[j], corners[(j + 1) % 4]));
  return min;
}
export function validateMaritimeLayout(placements: readonly MaritimePlacement[] = MARITIME_PLACEMENTS) {
  const problems: string[] = [];
  const ids = new Set<string>();
  const clearances = placements.map(p => {
    if (ids.has(p.id)) problems.push(`${p.id}: duplicate id`); ids.add(p.id);
    if (![p.x, p.z, p.yaw].every(Number.isFinite)) problems.push(`${p.id}: invalid pose`);
    if (isInsideTrackPolygon(p) || footprint(p).some(isInsideTrackPolygon)) problems.push(`${p.id}: inside track polygon`);
    const distance = minimumTrackClearance(p);
    // Roadbed is bounded by 12.5 m from the centreline; keep 10 m clear water.
    if (distance < 22.5) problems.push(`${p.id}: hull is only ${distance.toFixed(2)} m from centreline`);
    // Deliberately conservative exclusion around the full current pit complex.
    const corners = footprint(p);
    const bounds = { minX: Math.min(...corners.map(v => v.x)), maxX: Math.max(...corners.map(v => v.x)), minZ: Math.min(...corners.map(v => v.z)), maxZ: Math.max(...corners.map(v => v.z)) };
    if (bounds.maxX > 685 && bounds.minX < 760 && bounds.maxZ > -245 && bounds.minZ < 70) problems.push(`${p.id}: pit exclusion zone`);
    return { id: p.id, hullToCentreline: distance, clearWaterBeyondRoadbed: distance - 12.5 };
  });
  for (let i = 0; i < placements.length; i++) for (let j = i + 1; j < placements.length; j++) {
    const a = placements[i], b = placements[j];
    // Circumscribed radii are stricter than the oriented actual hulls.
    if (Math.hypot(a.x - b.x, a.z - b.z) < Math.hypot(a.halfBeam, a.halfLength) + Math.hypot(b.halfBeam, b.halfLength) + 8) problems.push(`${a.id}/${b.id}: insufficient vessel separation`);
  }
  return { valid: problems.length === 0, problems, clearances, yachts: placements.filter(p => p.kind === 'yacht').length, rescue: placements.filter(p => p.kind === 'rescue').length, routeLength: totalLength };
}
